class Solution:
    def shipWithinDays(self, weights, days):
        def can_ship(capacity):
            used = 1
            load = 0
            for weight in weights:
                if load + weight > capacity:
                    used += 1
                    load = 0
                load += weight
            return used <= days

        for capacity in range(max(weights), sum(weights) + 1):
            if can_ship(capacity):
                return capacity
        return sum(weights)

