class Solution:
    def shipWithinDays(self, weights, days):
        def needed_days(capacity):
            used = 1
            load = 0
            for weight in weights:
                if load + weight > capacity:
                    used += 1
                    load = 0
                load += weight
            return used

        lo, hi = max(weights), sum(weights)
        while lo < hi:
            mid = (lo + hi) // 2
            if needed_days(mid) <= days:
                hi = mid
            else:
                lo = mid + 1
        return lo

